        self.assertBad("2024-01-01 food", 1)
        self.assertBad("garbage", 1)

    def test_line_numbers_count_blank_and_comments(self):
        text = "# c\n\n2024-01-01 a 1\n   \n# d\n2024-01-02 a oops\n"
        self.assertBad(text, 6)

    def test_first_bad_line_reported(self):
        self.assertBad("2024-01-01 a 1\nbad\nworse\n", 2)

    def test_crlf_line_numbers(self):
        self.assertBad("2024-01-01 a 1\r\n\r\n2024-01-02 a x\r\n", 3)

    def test_non_ascii_digits_rejected(self):
        self.assertBad("2024-01-01 a ١٢", 1)


